sp_widget.css:
/* Main Header */

.campus-header {
    width: 100%;
    height: 70px;

    background: #ffffff;

    display: flex;
    align-items: center;
    justify-content: space-between;

    padding: 0 28px;

    box-sizing: border-box;

    border-bottom: 1px solid #e5e7eb;

    position: relative;
    z-index: 1000;
}


/* =========================
   LEFT SIDE
   ========================= */

.brand-section {
    display: flex;
    align-items: center;

    gap: 10px;
}


.brand-logo {
    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 25px;

    background: #f3f4f6;

    border-radius: 10px;
}


.brand-name {
    font-size: 21px;
    font-weight: 700;

    color: #1f2937;
}


/* =========================
   RIGHT SIDE
   ========================= */

.profile-section {
    position: relative;
}


.profile-button {
    border: none;

    background: transparent;

    display: flex;
    align-items: center;

    gap: 10px;

    padding: 8px 12px;

    cursor: pointer;

    border-radius: 8px;

    transition: background 0.2s ease;
}


.profile-button:hover {
    background: #f3f4f6;
}


.user-name {
    font-size: 15px;
    font-weight: 600;

    color: #374151;
}


.profile-icon {
    width: 36px;
    height: 36px;

    border-radius: 50%;

    background: #eef2ff;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 18px;
}


.arrow {
    font-size: 11px;

    color: #6b7280;

    transition: transform 0.2s ease;
}


.arrow.open {
    transform: rotate(180deg);
}


/* =========================
   DROPDOWN
   ========================= */

.profile-dropdown {
    position: absolute;

    top: 55px;
    right: 0;

    width: 220px;

    background: #ffffff;

    border: 1px solid #e5e7eb;

    border-radius: 10px;

    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.12);

    padding: 10px;

    box-sizing: border-box;
}


/* User information */

.profile-user {
    display: flex;

    align-items: center;

    gap: 10px;

    padding: 10px;
}


.dropdown-user-icon {
    width: 38px;
    height: 38px;

    border-radius: 50%;

    background: #eef2ff;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 18px;
}


.dropdown-user-name {
    font-size: 14px;

    font-weight: 600;

    color: #1f2937;
}


.dropdown-user-role {
    font-size: 12px;

    color: #6b7280;

    margin-top: 3px;
}


/* Divider */

.dropdown-divider {
    height: 1px;

    background: #e5e7eb;

    margin: 5px 0;
}


/* Logout */

.logout-button {
    width: 100%;

    border: none;

    background: transparent;

    display: flex;

    align-items: center;

    gap: 10px;

    padding: 10px;

    border-radius: 7px;

    cursor: pointer;

    font-size: 14px;

    color: #dc2626;

    text-align: left;
}


.logout-button:hover {
    background: #fef2f2;
}


/* =========================
   RESPONSIVE
   ========================= */

@media (max-width: 600px) {

    .campus-header {
        height: 60px;

        padding: 0 15px;
    }

    .brand-name {
        font-size: 18px;
    }

    .brand-logo {
        width: 36px;
        height: 36px;

        font-size: 21px;
    }

    .user-name {
        display: none;
    }

    .profile-dropdown {
        right: 0;
    }
}

sp_widget.script:
(function() {

    // Get logged-in user's name
    data.userName = gs.getUserDisplayName();

    // Get logged-in user's ID
    var userID = gs.getUserID();

    // Default role
    data.userRole = "USER";


    // Get user record
    var userGR = new GlideRecord('sys_user');

    if (userGR.get(userID)) {

        // Display user's name
        data.userName = userGR.getDisplayValue('name');

        // Check roles
        if (userGR.hasRole('admin')) {

            data.userRole = "ADMIN";

        } else if (userGR.hasRole('itil')) {

            data.userRole = "STAFF";

        } else {

            data.userRole = "STUDENT";

        }

    }

})();
